    input = sys.stdin.read().split()
    idx = 0
    G = int(input[idx])
    N = int(input[idx + 1])
    M = int(input[idx + 2])
    idx += 3

    mutation_table = {}
    for _ in range(N):
        a = int(input[idx])
        k = int(input[idx + 1])
        mutation_table[a] = [int(x) for x in input[idx + 2:idx + 2 + k]]
        idx += 2 + k

    antibodies = []
    for _ in range(M):
        l = int(input[idx])
        antibodies.append(tuple(int(x) for x in input[idx + 1:idx + 1 + l]))
        idx += 1 + l

    def bfs(start_gene):
        queue = deque([(start_gene, [])])
        visited = set([start_gene])
        while queue:
            current, path = queue.popleft()
            if current in mutation_table:
                for next_gene in mutation_table[current]:
                    new_path = path + [next_gene]
                    if next_gene not in visited:
                        visited.add(next_gene)
                        queue.append((next_gene, new_path))
            else:
                yield path

    def can_detect(path):
        sequence = []
        for gene in path:
            if gene == 0 or gene == 1:
                sequence.append(gene)
            else:
                return False
        sequence = tuple(sequence)
        for antibody in antibodies:
            if antibody in sequence:
                return True
        return False

    results = []
    for start_gene in range(2, G):
        min_length = float('inf')
        detected = False
        for path in bfs(start_gene):
            if can_detect(path):
                detected = True
            else:
                length = len(path)
                if length < min_length:
                    min_length = length
        if detected or min_length == float('inf'):
            results.append("YES")
        else:
            results.append(f"NO {min_length}")

    for result in results:
        print(result)

